   app4_0_approval_rules.sql   APP-4 stage 0: approval rule changes of 18 Nov (admin, both stages, return to a chosen person)
   GENERATED by tools/bundle_sql.py from the files listed below. Do not edit:
   change the source file and run `python tools/bundle_sql.py` again.
   Paste the whole file into New query of the ATLAS_SQL_DB item (type SQL database),
   run it once, and copy the Messages tab. Each file runs in its own batch.
   Files, in run order:
     db/procs/fn_stage_eligibility.sql
     db/procs/fn_return_candidates.sql
     db/procs/fn_return_rights.sql
     db/procs/fn_request_checks.sql
     db/procs/usp_request_decide.sql
     db/procs/usp_request_resubmit.sql
     db/procs/usp_request_cancel.sql
   ===================================================================== */
SET NOCOUNT ON;
PRINT N'=== app4_0_approval_rules: 7 file(s) ===';

PRINT N'--- db/procs/fn_stage_eligibility.sql';
EXEC (N'/* =====================================================================
   app.fn_stage_eligibility     APP-3 helper (used by the request procedures and
                                app.fn_request_checks, so the rule lives in ONE place)
   Single statement per file; CREATE OR ALTER, safe to run again.

   FINAL PLAN/01 section 3, "Approval eligibility": a person may decide a request at a stage
   when ALL of these hold:
     1. the stage''s flag is on in a role the person holds (can_responsible_approve for the
        RESPONSIBLE stage, can_accountable_approve for the ACCOUNTABLE stage), and
     2. the scope of that same role assignment covers the request''s profit centre (ALL_ORCM, or
        a list that contains it), and
     3. the person is an active member of the group the request was routed to for that stage.

   OR the person is an app admin (a registered person holding a role with can_manage_admin,
   app.fn_requester_rights): an admin may decide ANY stage of ANY request, without being in the group
   and without the stage''s flag (client, 18 Nov 2026; answers Q-479).

   Input : the person''s e-mail, the stage (RESPONSIBLE or ACCOUNTABLE), the routed group''s key
           and the request''s profit centre.
   Output: exactly one row
     is_group_member     3. (the group must also be active)
     has_flag_in_scope   1. and 2. together, on the same role assignment
     is_admin            the admin override above (independent of the stage)
     is_eligible         is_admin, or is_group_member and has_flag_in_scope (an unknown stage gives 0)

   A role is held when it is assigned to the person (USER) or to a group the person is an active
   member of (GROUP). An unknown stage, a missing group or a blank e-mail gives 0, never an error.
   One person approving both stages is NOT refused any more (client, 18 Nov 2026): whoever is eligible
   at the second stage may approve it, also when they approved the first one. That is only possible for
   an admin or for a member of both routed groups. The setting SAME_PERSON_BOTH_STAGES is no longer read.
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_stage_eligibility
(
    @user_email         nvarchar(256),
    @stage              nvarchar(12),
    @group_key          nvarchar(64),
    @profit_center_name nvarchar(40)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        CAST(z.mem  AS bit) AS is_group_member,
        CAST(z.flag AS bit) AS has_flag_in_scope,
        CAST(ISNULL(ad.can_manage_admin, 0) AS bit) AS is_admin,
        CAST(CASE WHEN @stage NOT IN (N''RESPONSIBLE'', N''ACCOUNTABLE'') OR @stage IS NULL THEN 0
                  WHEN ISNULL(ad.can_manage_admin, 0) = 1 THEN 1
                  WHEN z.mem = 1 AND z.flag = 1 THEN 1
                  ELSE 0 END AS bit) AS is_eligible
    FROM (SELECT LOWER(LTRIM(RTRIM(@user_email))) AS e) AS q
    OUTER APPLY app.fn_requester_rights(q.e) AS ad
    CROSS APPLY
    (
        SELECT
            CASE WHEN EXISTS (SELECT 1
                              FROM app.group_membership AS m
                              JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
                              WHERE m.is_active = 1 AND m.group_key = @group_key AND m.user_email = q.e) THEN 1 ELSE 0 END AS mem,
            CASE WHEN EXISTS (SELECT 1
                              FROM app.principal_role_assignment AS a
                              JOIN app.role AS ro ON ro.role_name = a.role_name AND ro.is_active = 1
                              WHERE a.is_active = 1
                                AND (CASE WHEN @stage = N''RESPONSIBLE'' THEN ro.can_responsible_approve
                                          WHEN @stage = N''ACCOUNTABLE'' THEN ro.can_accountable_approve
                                          ELSE 0 END) = 1
                                AND (   (a.principal_type = N''USER'' AND a.principal_key = q.e)
                                     OR (a.principal_type = N''GROUP''
                                         AND EXISTS (SELECT 1 FROM app.group_membership AS m2
                                                     WHERE m2.is_active = 1 AND m2.user_email = q.e AND m2.group_key = a.principal_key)))
                                AND (   a.scope_type = N''ALL_ORCM''
                                     OR EXISTS (SELECT 1 FROM app.principal_role_assignment_scope AS s
                                                WHERE s.assignment_id = a.assignment_id AND s.profit_center_name = @profit_center_name))) THEN 1 ELSE 0 END AS flag
    ) AS z
);
');

PRINT N'--- db/procs/fn_return_candidates.sql';
EXEC (N'/* =====================================================================
   app.fn_return_candidates     APP-4 change (client, 18 Nov 2026; answers Q-465)
                                (used by app.usp_request_decide to check a RETURN, app.fn_return_rights and
                                app.usp_request_detail for the Return dialog''s picker, so the list lives in ONE place)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.principal_identity, app.group_membership, app.security_group. Reads only.
   Test: db/tests/t_request_approval_rules.sql

   Who may a request be returned to "for correction"? The client: "anyone, including themselves". Agreed
   reading (18 Nov): the people who have something to do with the request:
     SUBMITTER          the person who raised it (not for a request raised by system:...)
     RESPONSIBLE_GROUP  an active member of the group the first stage is routed to
     ACCOUNTABLE_GROUP  an active member of the group the second stage is routed to
     YOU                @actor_email itself (the person returning it), whatever else is true
   Everyone except YOU must be a REGISTERED person (an active row in app.principal_identity), so a request is
   never returned to an address nobody signs in with. The groups must be active.

   Input : @request_id, @actor_email (NULL = list without "you": used to ask "is this person still a valid
           holder of a returned request?", app.fn_return_rights)
   Output: one row per person (a person who fits several reasons appears once, with the first reason in the
           order above, YOU last unless YOU is the only reason):
     user_email, display_name, relation (SUBMITTER, RESPONSIBLE_GROUP, ACCOUNTABLE_GROUP or YOU), sort_order,
     is_you (1 = this row is @actor_email, whatever its relation)
   An unknown request gives no rows.
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_return_candidates
(
    @request_id  bigint,
    @actor_email nvarchar(256)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        CAST(c.user_email AS nvarchar(256)) AS user_email,
        CAST(ISNULL(pi.display_name, c.user_email) AS nvarchar(256)) AS display_name,
        CAST(CASE MIN(c.prio) WHEN 1 THEN N''SUBMITTER'' WHEN 2 THEN N''RESPONSIBLE_GROUP''
                              WHEN 3 THEN N''ACCOUNTABLE_GROUP'' ELSE N''YOU'' END AS nvarchar(20)) AS relation,
        CAST(MIN(c.prio) AS int) AS sort_order,
        CAST(CASE WHEN c.user_email = LOWER(LTRIM(RTRIM(@actor_email))) THEN 1 ELSE 0 END AS bit) AS is_you
    FROM
    (
        SELECT LOWER(r.requested_by) AS user_email, 1 AS prio
        FROM app.change_request AS r
        WHERE r.request_id = @request_id
          AND LEFT(r.requested_by, 7) <> N''system:''
          AND EXISTS (SELECT 1 FROM app.principal_identity AS i WHERE i.user_email = LOWER(r.requested_by) AND i.is_active = 1)
        UNION ALL
        SELECT LOWER(m.user_email), CASE WHEN m.group_key = r.responsible_group THEN 2 ELSE 3 END
        FROM app.change_request AS r
        JOIN app.group_membership AS m ON m.is_active = 1 AND (m.group_key = r.responsible_group OR m.group_key = r.accountable_group)
        JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
        WHERE r.request_id = @request_id
          AND EXISTS (SELECT 1 FROM app.principal_identity AS i WHERE i.user_email = LOWER(m.user_email) AND i.is_active = 1)
        UNION ALL
        SELECT LOWER(LTRIM(RTRIM(@actor_email))), 9
        FROM app.change_request AS r
        WHERE r.request_id = @request_id
          AND @actor_email IS NOT NULL
          AND CHARINDEX(N''@'', @actor_email) > 1
          AND LEFT(LTRIM(@actor_email), 7) <> N''system:''
    ) AS c
    OUTER APPLY (SELECT TOP (1) p.display_name FROM app.principal_identity AS p
                 WHERE p.user_email = c.user_email AND p.is_active = 1) AS pi
    GROUP BY c.user_email, pi.display_name
);
');

PRINT N'--- db/procs/fn_return_rights.sql';
EXEC (N'/* =====================================================================
   app.fn_return_rights         APP-4 change (client, 18 Nov 2026; answers Q-465, edge case "the recipient left")
                                (used by app.usp_request_resubmit, app.fn_request_actions and app.usp_request_queue,
                                so the screens'' Resubmit button, the "Returned to me" tab and the procedure agree)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_return_candidates, app.fn_requester_rights. Reads only.
   Test: db/tests/t_request_approval_rules.sql

   Who may pick up (correct and resubmit) a RETURNED request?
     1. the recipient: the person it was returned to (USER), or an active member of the group (GROUP: a request
        the system raised, returned to the rule''s resolution group or the responsible group)
     2. when the return is ORPHANED, also: the submitter, an active member of the responsible group, an admin.
        Orphaned means nobody valid holds it any more:
          USER   the recipient is no longer a valid recipient: not registered any more, or no longer the submitter,
                 a member of either routed group or an admin (app.fn_return_candidates without "you")
          GROUP  the group is inactive or has no active member left
   "Raised by" never changes; the picking up is visible in the history (the RESUBMITTED event names who did it).

   Input : @request_id, @actor_email.
   Output: one row per existing request (none for an unknown id):
     is_recipient   1 = rule 1
     is_orphaned    1 = the return is orphaned (only meaningful while RETURNED; 0 otherwise)
     can_resubmit   1 = the request is RETURNED, the actor is a person, and rule 1 or (orphaned and rule 2)
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_return_rights
(
    @request_id  bigint,
    @actor_email nvarchar(256)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        r.request_id,
        CAST(x.is_recipient AS bit) AS is_recipient,
        CAST(x.is_orphaned  AS bit) AS is_orphaned,
        CAST(CASE WHEN r.request_status = N''RETURNED'' AND a.is_person = 1
                   AND (x.is_recipient = 1 OR (x.is_orphaned = 1 AND x.is_fallback = 1)) THEN 1 ELSE 0 END AS bit) AS can_resubmit
    FROM app.change_request AS r
    CROSS APPLY (SELECT LOWER(LTRIM(RTRIM(@actor_email))) AS e) AS a0
    CROSS APPLY (SELECT a0.e,
                        CASE WHEN a0.e IS NOT NULL AND CHARINDEX(N''@'', a0.e) > 1 AND LEFT(a0.e, 7) <> N''system:'' THEN 1 ELSE 0 END AS is_person) AS a
    OUTER APPLY app.fn_requester_rights(a.e) AS me
    OUTER APPLY app.fn_requester_rights(CASE WHEN r.return_recipient_type = N''USER'' THEN LOWER(r.return_recipient) END) AS rec
    CROSS APPLY
    (
        SELECT
            CASE WHEN a.is_person = 1
                  AND (   (r.return_recipient_type = N''USER'' AND LOWER(r.return_recipient) = a.e)
                       OR (r.return_recipient_type = N''GROUP''
                           AND EXISTS (SELECT 1 FROM app.group_membership AS m
                                       JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
                                       WHERE m.group_key = r.return_recipient AND m.is_active = 1 AND m.user_email = a.e)))
                 THEN 1 ELSE 0 END AS is_recipient,
            CASE WHEN r.request_status <> N''RETURNED'' THEN 0
                 WHEN r.return_recipient_type = N''USER''
                      AND ISNULL(rec.can_manage_admin, 0) = 0
                      AND NOT EXISTS (SELECT 1 FROM app.fn_return_candidates(r.request_id, NULL) AS c
                                      WHERE c.user_email = LOWER(r.return_recipient)) THEN 1
                 WHEN r.return_recipient_type = N''GROUP''
                      AND NOT EXISTS (SELECT 1 FROM app.group_membership AS m
                                      JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
                                      WHERE m.group_key = r.return_recipient AND m.is_active = 1) THEN 1
                 WHEN r.return_recipient_type IS NULL OR r.return_recipient IS NULL THEN 1
                 ELSE 0 END AS is_orphaned,
            CASE WHEN a.is_person = 0 THEN 0
                 WHEN LOWER(r.requested_by) = a.e THEN 1
                 WHEN ISNULL(me.can_manage_admin, 0) = 1 THEN 1
                 WHEN EXISTS (SELECT 1 FROM app.group_membership AS m
                              JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
                              WHERE m.group_key = r.responsible_group AND m.is_active = 1 AND m.user_email = a.e) THEN 1
                 ELSE 0 END AS is_fallback
    ) AS x
    WHERE r.request_id = @request_id
);
');

PRINT N'--- db/procs/fn_request_checks.sql';
EXEC (N'/* =====================================================================
   app.fn_request_checks        APP-3; FINAL PLAN/03 APP-3 step 2, REF-52 [L0189-L0190]
                                (used by app.usp_request_checks and app.usp_request_decide)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs the gold views (the synthetic stub or the data engineer''s): gold.vw_equipment_current,
   gold.vw_equipment_field_current, gold.vw_floc_current; and app.fn_stage_eligibility,
   app.fn_value_check.

   The approval checks of one request, live, as the approver would see them. Six rows, always in
   this order, each with PASS, FAIL or NOT_CHECKED, a plain-English message and the time:

     1 ASSOCIATION_MATCH            the heater is still at the functional location (FLOC) the request
                                    was raised at (for a FLOC request: the FLOC still exists)
     2 OLD_VALUE_CURRENT            the golden value is still the value the requester saw (numbers
                                    compare as numbers, text compares exactly, blank equals blank)
     3 VALUE_ALLOWED                the proposed value is still acceptable (app.fn_value_check)
     4 UNITS_EXPLICIT               a numeric field must carry its unit in the catalogue [INFERRED
                                    reading of "units explicit"]
     5 NO_CONFLICTING_OPEN_REQUEST  no other open request proposes a different value for the same field
                                    of the same heater (or FLOC)
     6 USER_ELIGIBLE_FOR_STAGE      the person named in @actor_email may decide this stage: flag, scope
                                    and group, or an admin (app.fn_stage_eligibility). Approving both
                                    stages is allowed since 18 Nov 2026 (client; Q-479)

   A request that is not waiting for a decision (status other than PENDING_RESPONSIBLE or
   PENDING_ACCOUNTABLE) gets NOT_CHECKED on every row: the checks mean something only while a person
   is about to decide, and a merged request would otherwise "fail" check 2 because the value changed.
   A blank @actor_email gives NOT_CHECKED on row 6 (the detail screen can show checks without a user).
   An unknown request id returns no rows.

   Input : @request_id, @actor_email (the person who is about to decide; may be NULL)
   Output: request_id, request_status, check_order, check_code, check_status, message, checked_at_utc

   The approval procedure blocks only on FAIL of rows 1 to 5 (row 6 it enforces itself, with its own
   refusal). NOT_CHECKED never blocks.
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_request_checks
(
    @request_id  bigint,
    @actor_email nvarchar(256)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        r.request_id,
        r.request_status,
        c.check_order,
        CAST(c.check_code   AS nvarchar(40))  AS check_code,
        CAST(c.check_status AS nvarchar(12))  AS check_status,
        CAST(c.message      AS nvarchar(400)) AS message,
        SYSUTCDATETIME() AS checked_at_utc
    FROM app.change_request AS r
    LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
    OUTER APPLY (SELECT TOP (1) 1 AS ok, e.functional_location AS floc
                 FROM gold.vw_equipment_current AS e
                 WHERE r.entity_type = N''EQUIPMENT'' AND e.equipment_id = r.equipment_id) AS ge
    OUTER APPLY (SELECT TOP (1) f.current_value AS val
                 FROM gold.vw_equipment_field_current AS f
                 WHERE r.entity_type = N''EQUIPMENT'' AND f.equipment_id = r.equipment_id AND f.field_code = r.field_code) AS gv
    OUTER APPLY (SELECT TOP (1) 1 AS ok, l.floc_class AS floc_class
                 FROM gold.vw_floc_current AS l
                 WHERE r.entity_type = N''FLOC'' AND l.functional_location = r.functional_location) AS gl
    CROSS APPLY (SELECT CASE r.request_status WHEN N''PENDING_RESPONSIBLE'' THEN N''RESPONSIBLE''
                                              WHEN N''PENDING_ACCOUNTABLE'' THEN N''ACCOUNTABLE''
                                              ELSE NULL END AS stage) AS st
    CROSS APPLY (SELECT CASE st.stage WHEN N''RESPONSIBLE'' THEN r.responsible_group
                                      WHEN N''ACCOUNTABLE'' THEN r.accountable_group
                                      ELSE NULL END AS grp) AS sg
    CROSS APPLY (SELECT LOWER(LTRIM(RTRIM(@actor_email))) AS a) AS ac
    CROSS APPLY (SELECT CASE WHEN r.entity_type = N''EQUIPMENT'' OR r.field_code = N''FLOC_CLASS'' THEN 1 ELSE 0 END AS supported,
                         CASE WHEN r.entity_type = N''EQUIPMENT'' THEN ge.ok ELSE gl.ok END AS known,
                         CASE WHEN r.entity_type = N''EQUIPMENT'' THEN gv.val ELSE gl.floc_class END AS cur) AS k
    CROSS APPLY (SELECT ISNULL(LTRIM(RTRIM(r.old_value)), N'''') AS oldv,
                         ISNULL(LTRIM(RTRIM(k.cur)), N'''')       AS curv,
                         ISNULL(LTRIM(RTRIM(r.new_value)), N'''') AS newv) AS t
    CROSS APPLY (SELECT CASE WHEN t.oldv COLLATE Latin1_General_BIN2 = t.curv COLLATE Latin1_General_BIN2 THEN 1
                             WHEN fc.data_type = N''DECIMAL''
                                  AND TRY_CONVERT(decimal(18,4), NULLIF(t.oldv, N'''')) = TRY_CONVERT(decimal(18,4), NULLIF(t.curv, N'''')) THEN 1
                             ELSE 0 END AS eq) AS q
    OUTER APPLY app.fn_value_check(r.field_code, r.new_value) AS vc
    OUTER APPLY (SELECT TOP (1) o.request_ref AS ref
                 FROM app.change_request AS o
                 WHERE o.request_id <> r.request_id
                   AND o.request_status <> N''APPROVED'' AND o.request_status <> N''REJECTED'' AND o.request_status <> N''CANCELLED''
                   AND o.field_code = r.field_code
                   AND (   (r.entity_type = N''EQUIPMENT'' AND o.equipment_id = r.equipment_id)
                        OR (r.entity_type = N''FLOC'' AND o.entity_type = N''FLOC'' AND o.functional_location = r.functional_location))
                   AND ISNULL(o.new_value, N'''') COLLATE Latin1_General_BIN2 <> t.newv COLLATE Latin1_General_BIN2
                 ORDER BY o.request_id) AS cf
    OUTER APPLY app.fn_stage_eligibility(ac.a, st.stage, sg.grp, r.profit_center_name) AS el
    CROSS APPLY
    (
        SELECT
            N''the request is '' + r.request_status + N'': checks apply only while it waits for a decision'' AS notpending,

            -- 1 ASSOCIATION_MATCH
            CASE WHEN st.stage IS NULL THEN N''NOT_CHECKED''
                 WHEN r.entity_type = N''EQUIPMENT'' AND ge.ok IS NULL THEN N''FAIL''
                 WHEN r.entity_type = N''EQUIPMENT'' AND r.functional_location IS NULL THEN N''NOT_CHECKED''
                 WHEN r.entity_type = N''EQUIPMENT''
                      AND ISNULL(ge.floc, N'''') COLLATE Latin1_General_BIN2 = r.functional_location COLLATE Latin1_General_BIN2 THEN N''PASS''
                 WHEN r.entity_type = N''EQUIPMENT'' THEN N''FAIL''
                 WHEN r.entity_type = N''FLOC'' AND gl.ok IS NULL THEN N''FAIL''
                 WHEN r.entity_type = N''FLOC'' THEN N''PASS''
                 ELSE N''NOT_CHECKED'' END AS c1s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.entity_type = N''EQUIPMENT'' AND ge.ok IS NULL THEN N''the heater is no longer in gold''
                 WHEN r.entity_type = N''EQUIPMENT'' AND r.functional_location IS NULL THEN N''no location was stored with the request''
                 WHEN r.entity_type = N''EQUIPMENT''
                      AND ISNULL(ge.floc, N'''') COLLATE Latin1_General_BIN2 = r.functional_location COLLATE Latin1_General_BIN2
                      THEN N''the heater is still at the location the request was raised at''
                 WHEN r.entity_type = N''EQUIPMENT''
                      THEN N''the heater is now at '' + LEFT(ISNULL(ge.floc, N''(none)''), 60) + N'', the request was raised at '' + LEFT(r.functional_location, 60)
                 WHEN r.entity_type = N''FLOC'' AND gl.ok IS NULL THEN N''the functional location is no longer in gold''
                 WHEN r.entity_type = N''FLOC'' THEN N''the functional location still exists''
                 ELSE N''not applicable'' END AS c1m,

            -- 2 OLD_VALUE_CURRENT
            CASE WHEN st.stage IS NULL THEN N''NOT_CHECKED''
                 WHEN k.supported = 0 THEN N''NOT_CHECKED''
                 WHEN k.known IS NULL THEN N''FAIL''
                 WHEN q.eq = 1 THEN N''PASS''
                 ELSE N''FAIL'' END AS c2s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN k.supported = 0 THEN N''the current value of this field is not read from gold yet''
                 WHEN k.known IS NULL THEN N''the heater or location is no longer in gold''
                 WHEN q.eq = 1 THEN N''the current value is still the one the request expected''
                 ELSE N''the current value is "'' + LEFT(t.curv, 100) + N''", the request expected "'' + LEFT(t.oldv, 100) + N''"'' END AS c2m,

            -- 3 VALUE_ALLOWED
            CASE WHEN st.stage IS NULL OR r.field_code IS NULL THEN N''NOT_CHECKED''
                 WHEN vc.problem IS NULL THEN N''PASS''
                 ELSE N''FAIL'' END AS c3s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.field_code IS NULL THEN N''no catalogue field to check against''
                 WHEN vc.problem IS NULL THEN N''the proposed value is allowed''
                 ELSE vc.problem END AS c3m,

            -- 4 UNITS_EXPLICIT
            CASE WHEN st.stage IS NULL OR r.field_code IS NULL THEN N''NOT_CHECKED''
                 WHEN fc.data_type = N''DECIMAL'' AND fc.unit IS NULL THEN N''FAIL''
                 ELSE N''PASS'' END AS c4s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.field_code IS NULL THEN N''no catalogue field to check against''
                 WHEN fc.data_type = N''DECIMAL'' AND fc.unit IS NULL THEN N''this numeric field has no unit in the catalogue, so the unit is not explicit''
                 WHEN fc.data_type = N''DECIMAL'' THEN N''the unit is '' + fc.unit + N'', from the catalogue''
                 ELSE N''no unit applies to this field'' END AS c4m,

            -- 5 NO_CONFLICTING_OPEN_REQUEST
            CASE WHEN st.stage IS NULL OR r.field_code IS NULL THEN N''NOT_CHECKED''
                 WHEN cf.ref IS NOT NULL THEN N''FAIL''
                 ELSE N''PASS'' END AS c5s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.field_code IS NULL THEN N''no catalogue field to check against''
                 WHEN cf.ref IS NOT NULL THEN N''request '' + cf.ref + N'' is also open on this field with a different value''
                 ELSE N''no other open request proposes a different value'' END AS c5m,

            -- 6 USER_ELIGIBLE_FOR_STAGE
            CASE WHEN st.stage IS NULL THEN N''NOT_CHECKED''
                 WHEN ac.a IS NULL OR ac.a = N'''' THEN N''NOT_CHECKED''
                 WHEN el.is_eligible = 1 THEN N''PASS''
                 ELSE N''FAIL'' END AS c6s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN ac.a IS NULL OR ac.a = N'''' THEN N''no approver was named, so eligibility was not checked''
                 WHEN el.is_group_member = 1 AND el.has_flag_in_scope = 1 THEN N''allowed to decide the '' + st.stage + N'' stage''
                 WHEN el.is_admin = 1 THEN N''allowed to decide the '' + st.stage + N'' stage as an admin (not a member of '' + ISNULL(sg.grp, N''the group'') + N'')''
                 WHEN el.is_group_member = 0 THEN N''not an active member of the group for this stage ('' + ISNULL(sg.grp, N''none'') + N'')''
                 ELSE N''no role of this person allows the '' + st.stage + N'' stage for '' + LEFT(r.profit_center_name, 40) END AS c6m
    ) AS x
    CROSS APPLY (VALUES
        (1, N''ASSOCIATION_MATCH'',           x.c1s, ISNULL(x.c1m, x.notpending)),
        (2, N''OLD_VALUE_CURRENT'',           x.c2s, ISNULL(x.c2m, x.notpending)),
        (3, N''VALUE_ALLOWED'',               x.c3s, ISNULL(x.c3m, x.notpending)),
        (4, N''UNITS_EXPLICIT'',              x.c4s, ISNULL(x.c4m, x.notpending)),
        (5, N''NO_CONFLICTING_OPEN_REQUEST'', x.c5s, ISNULL(x.c5m, x.notpending)),
        (6, N''USER_ELIGIBLE_FOR_STAGE'',     x.c6s, ISNULL(x.c6m, x.notpending))
    ) AS c (check_order, check_code, check_status, message)
    WHERE r.request_id = @request_id
);
');

PRINT N'--- db/procs/usp_request_decide.sql';
EXEC (N'/* =====================================================================
   app.usp_request_decide       APP-3; FINAL PLAN/01 section 2.2 (write path), 03 APP-3 step 3;
                                tests: db/tests/t_request_lifecycle.sql
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_stage_eligibility, app.fn_request_checks, app.usp_notification_enqueue.

   One approver decides one request: APPROVE, REJECT or RETURN. All the rules live here (the function
   only identifies the caller). In order; a refusal is a THROW and nothing is written:

     50131 the actor must be a person''s e-mail (never a system:... name)      50132 unknown decision
     50133 no such request                                                     50134 not waiting for a decision
     50135 @expected_status given and the request has moved on (the screen is out of date)
     50136 REJECT and RETURN need a comment
     50141 not an active member of the group the request was routed to for this stage (an admin is exempt)
     50142 no role of the person has the stage''s flag with a scope that covers the profit centre (an admin is
           exempt)
     (50143, "the same person may not approve both stages", is retired: client, 18 Nov 2026, answers Q-479.
      Whoever is eligible at the second stage may approve it, also when they approved the first: an admin, or
      a member of both routed groups. The event records how: decided_as ADMIN or GROUP_MEMBER, and
      same_person_both_stages = true.)
     50144 APPROVE blocked by a FAILED approval check (app.fn_request_checks rows 1 to 5; NOT_CHECKED does
           not block; a stale request can still be REJECTED or RETURNED)
     50137 RETURN to someone who is not allowed (client, 18 Nov 2026, answers Q-465). @return_recipient names
           ONE person, who must be in app.fn_return_candidates for this request and this actor: the submitter,
           an active member of either routed group (registered), or the actor themselves. Without
           @return_recipient the request goes where it went before (the default): the submitter of a field or
           manual request, the rule''s resolution group for a rule request, the responsible group for another
           request raised by system:... . @return_recipient_type, when given, must be USER with a person, or
           GROUP with exactly that default group.
     50149 somebody else changed the request between the read and the write (row_version)

   What it writes, in ONE transaction: the new status, the event (type, stage, actor, group, comment,
   status before and after, the check results as JSON), and the notifications:
     APPROVE at RESPONSIBLE   -> PENDING_ACCOUNTABLE, event RESPONSIBLE_APPROVED, group notified
     APPROVE at ACCOUNTABLE   -> APPROVED, event ACCOUNTABLE_APPROVED, requester notified; needs_merge = 1
     REJECT                   -> REJECTED, event REJECTED, requester notified with the comment
     RETURN                   -> RETURNED, event RETURNED, the recipient notified with the comment (not when the
                                 actor returned it to themselves)
   The merge into gold is NOT done here: it is a separate step after the approval commits (01 section 2.2).
   The function calls gold.usp_apply_approved_change when needs_merge = 1 and records the outcome with
   app.usp_request_record_merge.

   Result: ONE row (request_id, request_ref, decision, previous_status, new_status, stage, needs_merge) when
   @emit_result = 1 (the default), and always @o_new_status and @o_needs_merge. app.usp_request_bulk_decide
   passes @emit_result = 0. Do not call this procedure from INSERT ... EXEC; read the OUTPUT parameters.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_decide
    @request_id            bigint,
    @actor_email           nvarchar(256),
    @decision              nvarchar(10),
    @comment               nvarchar(1000) = NULL,
    @expected_status       nvarchar(24)   = NULL,
    @return_recipient_type nvarchar(10)   = NULL,
    @return_recipient      nvarchar(256)  = NULL,
    @emit_result           bit            = 1,
    @o_new_status          nvarchar(24)   = NULL OUTPUT,
    @o_needs_merge         bit            = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @dec nvarchar(10) = UPPER(LTRIM(RTRIM(@decision)));
    DECLARE @cmt nvarchar(1000) = NULLIF(LTRIM(RTRIM(@comment)), N'''');

    IF @actor IS NULL OR CHARINDEX(N''@'', @actor) < 2 OR LEFT(@actor, 7) = N''system:''
        THROW 50131, N''The decision must come from a person (an e-mail address).'', 1;
    IF @dec IS NULL OR @dec NOT IN (N''APPROVE'', N''REJECT'', N''RETURN'')
        THROW 50132, N''The decision must be APPROVE, REJECT or RETURN.'', 1;

    /* ---- the request -------------------------------------------------------------- */
    DECLARE @status nvarchar(24), @rg nvarchar(64), @ag nvarchar(64), @pc nvarchar(40), @source nvarchar(20);
    DECLARE @rule nvarchar(64), @rv int, @by nvarchar(256), @ref nvarchar(12), @rowver binary(8);
    SELECT @status = r.request_status, @rg = r.responsible_group, @ag = r.accountable_group, @pc = r.profit_center_name,
           @source = r.source_type, @rule = r.source_rule_id, @rv = r.source_rule_version, @by = r.requested_by,
           @ref = r.request_ref, @rowver = r.row_version
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50133, N''That request does not exist.'', 1;
    IF @status NOT IN (N''PENDING_RESPONSIBLE'', N''PENDING_ACCOUNTABLE'')
    BEGIN
        SET @msg = N''The request is '' + @status + N''; only a request that waits for a decision can be decided.'';
        THROW 50134, @msg, 1;
    END
    IF @expected_status IS NOT NULL AND @expected_status <> @status
    BEGIN
        SET @msg = N''The request is now '' + @status + N'', not '' + @expected_status + N'': reload it and decide again.'';
        THROW 50135, @msg, 1;
    END

    DECLARE @stage nvarchar(12) = CASE WHEN @status = N''PENDING_RESPONSIBLE'' THEN N''RESPONSIBLE'' ELSE N''ACCOUNTABLE'' END;
    DECLARE @grp nvarchar(64) = CASE WHEN @stage = N''RESPONSIBLE'' THEN @rg ELSE @ag END;

    IF @dec IN (N''REJECT'', N''RETURN'') AND @cmt IS NULL
        THROW 50136, N''A comment is required to reject or return a request.'', 1;

    /* ---- who may decide ---------------------------------------------------------- */
    DECLARE @is_member bit, @has_flag bit, @is_admin bit;
    SELECT @is_member = e.is_group_member, @has_flag = e.has_flag_in_scope, @is_admin = e.is_admin
    FROM app.fn_stage_eligibility(@actor, @stage, @grp, @pc) AS e;
    IF ISNULL(@is_admin, 0) = 0 AND @is_member = 0
    BEGIN
        SET @msg = N''You are not an active member of the group for this stage ('' + ISNULL(@grp, N''none'') + N'').'';
        THROW 50141, @msg, 1;
    END
    IF ISNULL(@is_admin, 0) = 0 AND @has_flag = 0
    BEGIN
        SET @msg = N''No role of yours allows the '' + @stage + N'' stage for '' + ISNULL(@pc, N''this profit centre'') + N''.'';
        THROW 50142, @msg, 1;
    END
    -- how this person qualified, for the history: a group member with the flag, or an admin who is not
    DECLARE @decided_as nvarchar(12) = CASE WHEN @is_member = 1 AND @has_flag = 1 THEN N''GROUP_MEMBER'' ELSE N''ADMIN'' END;
    DECLARE @same_person bit = CASE WHEN @dec = N''APPROVE'' AND @stage = N''ACCOUNTABLE''
                                     AND EXISTS (SELECT 1 FROM app.change_request_event AS ev
                                                 WHERE ev.request_id = @request_id AND ev.event_type = N''RESPONSIBLE_APPROVED'' AND ev.actor = @actor)
                                    THEN 1 ELSE 0 END;

    /* ---- approval checks (a stale or failing request may still be rejected or returned) -- */
    DECLARE @failed nvarchar(max);
    IF @dec = N''APPROVE''
    BEGIN
        SELECT @failed = STRING_AGG(CAST(c.check_code AS nvarchar(max)), N'', '')
        FROM app.fn_request_checks(@request_id, @actor) AS c
        WHERE c.check_status = N''FAIL'' AND c.check_code <> N''USER_ELIGIBLE_FOR_STAGE'';
        IF @failed IS NOT NULL
        BEGIN
            SET @msg = N''Approval is blocked by failed checks: '' + LEFT(@failed, 600) + N''.'';
            THROW 50144, @msg, 1;
        END
    END
    DECLARE @checks_json nvarchar(max) =
        (SELECT c.check_code AS code, c.check_status AS status
         FROM app.fn_request_checks(@request_id, @actor) AS c
         ORDER BY c.check_order
         FOR JSON PATH);

    /* ---- who a returned request goes to --------------------------------------------- */
    DECLARE @rtype nvarchar(10) = NULL, @rrec nvarchar(256) = NULL;
    IF @dec = N''RETURN''
    BEGIN
        IF @source = N''BUSINESS_RULE''
        BEGIN
            SET @rtype = N''GROUP'';
            SELECT @rrec = br.resolution_group FROM app.business_rules AS br WHERE br.rule_id = @rule AND br.rule_version = @rv;
            IF @rrec IS NULL SET @rrec = @rg;
        END
        ELSE IF LEFT(@by, 7) <> N''system:''
        BEGIN
            SET @rtype = N''USER'';
            SET @rrec = @by;
        END
        ELSE
        BEGIN
            SET @rtype = N''GROUP'';
            SET @rrec = @rg;
        END

        -- a chosen recipient (client, 18 Nov 2026): one person from app.fn_return_candidates, or the default group
        DECLARE @want_type nvarchar(10) = NULLIF(UPPER(LTRIM(RTRIM(@return_recipient_type))), N'''');
        DECLARE @want nvarchar(256) = NULLIF(LOWER(LTRIM(RTRIM(@return_recipient))), N'''');
        IF @want IS NOT NULL OR @want_type IS NOT NULL
        BEGIN
            IF @want_type = N''GROUP''
            BEGIN
                IF @rtype <> N''GROUP'' OR @want IS NULL OR @want <> LOWER(@rrec)
                BEGIN
                    SET @msg = N''This request can only be returned to a person, or to '' + CASE WHEN @rtype = N''GROUP'' THEN @rrec ELSE N''no group'' END + N''.'';
                    THROW 50137, @msg, 1;
                END
            END
            ELSE
            BEGIN
                IF (@want_type IS NOT NULL AND @want_type <> N''USER'')
                   OR @want IS NULL
                   OR NOT EXISTS (SELECT 1 FROM app.fn_return_candidates(@request_id, @actor) AS c WHERE c.user_email = @want)
                    THROW 50137, N''A request can only be returned to its submitter, to a registered member of one of its two approval groups, or to yourself.'', 1;
                SET @rtype = N''USER'';
                SET @rrec = @want;
            END
        END
    END

    /* ---- write ---------------------------------------------------------------------- */
    DECLARE @new_status nvarchar(24) = CASE WHEN @dec = N''REJECT'' THEN N''REJECTED''
                                            WHEN @dec = N''RETURN'' THEN N''RETURNED''
                                            WHEN @stage = N''RESPONSIBLE'' THEN N''PENDING_ACCOUNTABLE''
                                            ELSE N''APPROVED'' END;
    DECLARE @event_type nvarchar(24) = CASE WHEN @dec = N''REJECT'' THEN N''REJECTED''
                                            WHEN @dec = N''RETURN'' THEN N''RETURNED''
                                            WHEN @stage = N''RESPONSIBLE'' THEN N''RESPONSIBLE_APPROVED''
                                            ELSE N''ACCOUNTABLE_APPROVED'' END;
    DECLARE @details nvarchar(max) =
        (SELECT @stage AS stage, @dec AS decision, @decided_as AS decided_as,
                CAST(@same_person AS bit) AS same_person_both_stages, JSON_QUERY(@checks_json) AS checks,
                @rtype AS return_recipient_type, @rrec AS return_recipient
         FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @req_mail nvarchar(256) = CASE WHEN @by = @actor THEN NULL ELSE @by END;
    DECLARE @ret_mail nvarchar(256) = CASE WHEN @rtype = N''USER'' AND @rrec <> @actor THEN @rrec ELSE NULL END;
    DECLARE @ret_group nvarchar(64) = CASE WHEN @rtype = N''GROUP'' THEN @rrec ELSE NULL END;
    DECLARE @what nvarchar(400) = (SELECT TOP (1) ISNULL(fc.label, r.field_code) + N'' of '' + ISNULL(r.equipment_number, r.functional_location)
                                   FROM app.change_request AS r
                                   LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
                                   WHERE r.request_id = @request_id);
    DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    DECLARE @event_id bigint, @ek nvarchar(60), @t nvarchar(200), @b nvarchar(1000);

    BEGIN TRY
        IF @own = 1 BEGIN TRANSACTION;

        UPDATE app.change_request
        SET request_status = @new_status,
            updated_at_utc = SYSUTCDATETIME(),
            return_recipient_type = @rtype,
            return_recipient = @rrec
        WHERE request_id = @request_id AND request_status = @status AND row_version = @rowver;
        IF @@ROWCOUNT <> 1
            THROW 50149, N''Somebody else changed this request at the same moment: reload it and try again.'', 1;

        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, @event_type, @stage, @actor, @grp, @cmt, @status, @new_status, @details);
        SET @event_id = SCOPE_IDENTITY();
        SET @ek = N''E'' + CAST(@event_id AS nvarchar(20));

        IF @dec = N''APPROVE'' AND @stage = N''RESPONSIBLE''
        BEGIN
            SET @t = N''Request '' + @ref + N'' needs your approval'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' passed the responsible stage and now waits for the accountable stage.'', 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_PENDING_ACCOUNTABLE'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_group = @ag;
        END
        ELSE IF @dec = N''APPROVE''
        BEGIN
            SET @t = N''Request '' + @ref + N'' was approved'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' was approved by both stages.'', 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_APPROVED'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_email = @req_mail;
        END
        ELSE IF @dec = N''REJECT''
        BEGIN
            SET @t = N''Request '' + @ref + N'' was rejected'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' was rejected. Comment: '' + @cmt, 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_REJECTED'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_email = @req_mail;
        END
        ELSE
        BEGIN
            SET @t = N''Request '' + @ref + N'' was returned to you'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' was returned. Comment: '' + @cmt, 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_RETURNED'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_email = @ret_mail, @recipient_group = @ret_group;
        END

        IF @own = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SET @o_new_status = @new_status;
    SET @o_needs_merge = CASE WHEN @new_status = N''APPROVED'' THEN 1 ELSE 0 END;

    IF @emit_result = 1
        SELECT @request_id AS request_id, @ref AS request_ref, @dec AS decision, @status AS previous_status,
               @new_status AS new_status, @stage AS stage, @o_needs_merge AS needs_merge;
END
');

PRINT N'--- db/procs/usp_request_resubmit.sql';
EXEC (N'/* =====================================================================
   app.usp_request_resubmit     APP-3; FINAL PLAN/03 APP-3 step 5; workflow POC_Final/04, step 3 of the
                                return loop ("recipient corrects the proposed value ... and resubmits")
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_value_check, app.usp_notification_enqueue.

   Sends a RETURNED request back to the first stage (PENDING_RESPONSIBLE), optionally with a corrected
   proposed value. Who may do it is app.fn_return_rights (client, 18 Nov 2026): the person it was returned to
   (any of the people app.fn_return_candidates allowed, not only the submitter), an active member of the group
   when it went to a GROUP; and, when that recipient can no longer act on it (orphaned), also the submitter, a
   member of the responsible group or an admin. "Raised by" never changes. A refusal is a THROW; nothing is written:

     50161 no such request                       50162 the request is not RETURNED
     50163 the person may not resubmit it (app.fn_return_rights)
     50120 the corrected value equals the old value
     50121 the corrected value is not acceptable (app.fn_value_check)
     50164 another open request already proposes that change (same de-duplication key)
     50165 another open request proposes a different value for the same field
     50149 somebody else changed the request at the same moment

   With a corrected value the de-duplication key is computed again (same formula as
   app.usp_request_create: rule id, entity type, entity key, field, old value, new value). Both approval
   stages start again; an earlier approval stays in the history and still counts for the segregation rule.
   One transaction: status, value, key, return recipient cleared, RESUBMITTED event (comment, old and new
   proposed value), notification to the responsible group.

   Result: ONE row (request_id, request_ref, previous_status, new_status, new_value) when @emit_result = 1,
   and always @o_new_status.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_resubmit
    @request_id   bigint,
    @actor_email  nvarchar(256),
    @new_value    nvarchar(400)  = NULL,
    @comment      nvarchar(1000) = NULL,
    @emit_result  bit            = 1,
    @o_new_status nvarchar(24)   = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @cmt nvarchar(1000) = NULLIF(LTRIM(RTRIM(@comment)), N'''');
    DECLARE @nv nvarchar(400) = NULLIF(LTRIM(RTRIM(@new_value)), N'''');

    DECLARE @status nvarchar(24), @etype nvarchar(10), @eqid int, @eqnum nvarchar(18), @floc nvarchar(40), @field nvarchar(64);
    DECLARE @oldv nvarchar(400), @curv nvarchar(400), @rule nvarchar(64), @rg nvarchar(64), @rtype nvarchar(10), @rrec nvarchar(256);
    DECLARE @ref nvarchar(12), @rowver binary(8);
    SELECT @status = r.request_status, @etype = r.entity_type, @eqid = r.equipment_id, @eqnum = r.equipment_number,
           @floc = r.functional_location, @field = r.field_code, @oldv = r.old_value, @curv = r.new_value,
           @rule = r.source_rule_id, @rg = r.responsible_group, @rtype = r.return_recipient_type, @rrec = r.return_recipient,
           @ref = r.request_ref, @rowver = r.row_version
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50161, N''That request does not exist.'', 1;
    IF @status <> N''RETURNED''
    BEGIN
        SET @msg = N''The request is '' + @status + N''; only a returned request can be resubmitted.'';
        THROW 50162, @msg, 1;
    END

    IF NOT EXISTS (SELECT 1 FROM app.fn_return_rights(@request_id, @actor) AS rr WHERE rr.can_resubmit = 1)
        THROW 50163, N''Only the person or group the request was returned to may resubmit it (or, when that person can no longer act on it, the submitter, a member of the responsible group or an admin).'', 1;

    /* ---- a corrected value ----------------------------------------------------------- */
    DECLARE @newv nvarchar(400) = @curv;
    DECLARE @key char(64) = NULL;
    IF @nv IS NOT NULL AND @nv COLLATE Latin1_General_BIN2 <> ISNULL(@curv, N'''') COLLATE Latin1_General_BIN2
    BEGIN
        DECLARE @ftype nvarchar(10) = (SELECT c.data_type FROM app.field_catalog AS c WHERE c.field_code = @field);
        DECLARE @problem nvarchar(400) = (SELECT v.problem FROM app.fn_value_check(@field, @nv) AS v);
        IF @problem IS NOT NULL
        BEGIN
            SET @msg = N''The corrected value is not acceptable: '' + @problem + N''.'';
            THROW 50121, @msg, 1;
        END
        DECLARE @same bit = 0;
        IF @ftype = N''DECIMAL'' AND TRY_CONVERT(decimal(18,4), @nv) IS NOT NULL AND TRY_CONVERT(decimal(18,4), @oldv) IS NOT NULL
            SET @same = CASE WHEN TRY_CONVERT(decimal(18,4), @nv) = TRY_CONVERT(decimal(18,4), @oldv) THEN 1 ELSE 0 END;
        ELSE
            SET @same = CASE WHEN ISNULL(@oldv, N'''') COLLATE Latin1_General_BIN2 = @nv COLLATE Latin1_General_BIN2 THEN 1 ELSE 0 END;
        IF @same = 1
            THROW 50120, N''The corrected value is the same as the old value.'', 1;

        DECLARE @entity_key nvarchar(40) = CASE WHEN @etype = N''EQUIPMENT'' THEN @eqnum ELSE @floc END;
        SET @key = CONVERT(char(64), HASHBYTES(''SHA2_256'',
            CONCAT(ISNULL(@rule, N''''), NCHAR(31), @etype, NCHAR(31), @entity_key, NCHAR(31),
                   @field, NCHAR(31), ISNULL(@oldv, N''''), NCHAR(31), @nv)), 2);

        IF EXISTS (SELECT 1 FROM app.change_request AS d
                   WHERE d.deduplication_key = @key AND d.request_id <> @request_id
                     AND d.request_status <> N''APPROVED'' AND d.request_status <> N''REJECTED'' AND d.request_status <> N''CANCELLED'')
            THROW 50164, N''Another open request already proposes that change.'', 1;
        IF EXISTS (SELECT 1 FROM app.change_request AS o
                   WHERE o.request_id <> @request_id AND o.field_code = @field
                     AND o.request_status <> N''APPROVED'' AND o.request_status <> N''REJECTED'' AND o.request_status <> N''CANCELLED''
                     AND (   (@etype = N''EQUIPMENT'' AND o.equipment_id = @eqid)
                          OR (@etype = N''FLOC'' AND o.entity_type = N''FLOC'' AND o.functional_location = @floc))
                     AND ISNULL(o.new_value, N'''') COLLATE Latin1_General_BIN2 <> @nv COLLATE Latin1_General_BIN2)
            THROW 50165, N''Another open request proposes a different value for the same field.'', 1;
        SET @newv = @nv;
    END

    /* ---- write ----------------------------------------------------------------------- */
    DECLARE @details nvarchar(max) =
        (SELECT @curv AS previous_new_value, @newv AS new_value FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @what nvarchar(400) = (SELECT TOP (1) ISNULL(fc.label, r.field_code) + N'' of '' + ISNULL(r.equipment_number, r.functional_location)
                                   FROM app.change_request AS r
                                   LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
                                   WHERE r.request_id = @request_id);
    DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    DECLARE @event_id bigint, @ek nvarchar(60), @t nvarchar(200), @b nvarchar(1000);

    BEGIN TRY
        IF @own = 1 BEGIN TRANSACTION;

        UPDATE app.change_request
        SET request_status = N''PENDING_RESPONSIBLE'',
            new_value = @newv,
            deduplication_key = ISNULL(@key, deduplication_key),
            return_recipient_type = NULL,
            return_recipient = NULL,
            updated_at_utc = SYSUTCDATETIME()
        WHERE request_id = @request_id AND request_status = N''RETURNED'' AND row_version = @rowver;
        IF @@ROWCOUNT <> 1
            THROW 50149, N''Somebody else changed this request at the same moment: reload it and try again.'', 1;

        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, N''RESUBMITTED'', NULL, @actor, NULL, @cmt, N''RETURNED'', N''PENDING_RESPONSIBLE'', @details);
        SET @event_id = SCOPE_IDENTITY();
        SET @ek = N''E'' + CAST(@event_id AS nvarchar(20));

        SET @t = N''Request '' + @ref + N'' needs your approval again'';
        SET @b = LEFT(@ref + N'': '' + @what + N'' was resubmitted with the proposed value "'' + @newv + N''".'', 1000);
        EXEC app.usp_notification_enqueue @topic = N''REQUEST_PENDING_RESPONSIBLE'', @request_id = @request_id, @event_key = @ek,
                                          @title = @t, @body = @b, @recipient_group = @rg;

        IF @own = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SET @o_new_status = N''PENDING_RESPONSIBLE'';
    IF @emit_result = 1
        SELECT @request_id AS request_id, @ref AS request_ref, N''RETURNED'' AS previous_status,
               N''PENDING_RESPONSIBLE'' AS new_status, @newv AS new_value;
END
');

PRINT N'--- db/procs/usp_request_cancel.sql';
EXEC (N'/* =====================================================================
   app.usp_request_cancel       APP-3; FINAL PLAN/03 APP-3 step 5 ("requester withdraws")
   Single statement per file; CREATE OR ALTER, safe to run again.

   Withdraws an open request (PENDING_RESPONSIBLE, PENDING_ACCOUNTABLE, RETURNED or DRAFT): status
   CANCELLED, one CANCELLED event. The row stays (nothing is ever deleted). Closing it frees its
   de-duplication key, so the same change can be raised again by a person; a RULE source stays
   suppressed after a cancellation (app.usp_request_create, REF-52 [L0187]).

   Who may (changed 18 Nov 2026: a request can now be returned to people other than its submitter, and the
   agreed rule is "the recipient fixes it, the submitter keeps it"):
     - the person who raised it (requested_by), in any open status;
     - an admin (can_manage_admin, app.fn_requester_rights), in any open status;
     - while it is RETURNED to a GROUP (a request the system raised, which has no person as submitter), an
       active member of that group, who stands in for the submitter [INFERRED].
   A person it was returned to personally may correct and resubmit it but NOT withdraw it.
   A refusal is a THROW; nothing is written:
     50171 no such request        50172 the request is already closed (APPROVED, REJECTED or CANCELLED)
     50173 not the requester, not an admin, and not a member of the group a system request was returned to
     50149 somebody else changed the request at the same moment
   No notification is queued (the notification topics of 09 section 7.1 have none for a withdrawal).

   Result: ONE row (request_id, request_ref, previous_status, new_status) when @emit_result = 1,
   and always @o_new_status.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_cancel
    @request_id   bigint,
    @actor_email  nvarchar(256),
    @comment      nvarchar(1000) = NULL,
    @emit_result  bit            = 1,
    @o_new_status nvarchar(24)   = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @cmt nvarchar(1000) = NULLIF(LTRIM(RTRIM(@comment)), N'''');

    DECLARE @status nvarchar(24), @by nvarchar(256), @rtype nvarchar(10), @rrec nvarchar(256), @ref nvarchar(12), @rowver binary(8);
    SELECT @status = r.request_status, @by = r.requested_by, @rtype = r.return_recipient_type, @rrec = r.return_recipient,
           @ref = r.request_ref, @rowver = r.row_version
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50171, N''That request does not exist.'', 1;
    IF @status IN (N''APPROVED'', N''REJECTED'', N''CANCELLED'')
    BEGIN
        SET @msg = N''The request is already '' + @status + N''; it cannot be withdrawn.'';
        THROW 50172, @msg, 1;
    END

    IF @actor IS NULL OR @actor = N'''' OR LEFT(@actor, 7) = N''system:''
       OR NOT (   LOWER(@by) = @actor
               OR EXISTS (SELECT 1 FROM app.fn_requester_rights(@actor) AS ad WHERE ad.can_manage_admin = 1)
               OR (@status = N''RETURNED'' AND @rtype = N''GROUP''
                   AND EXISTS (SELECT 1 FROM app.group_membership AS m
                               WHERE m.group_key = @rrec AND m.is_active = 1 AND m.user_email = @actor)))
        THROW 50173, N''Only the person who raised the request, or an admin, may withdraw it.'', 1;

    DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    BEGIN TRY
        IF @own = 1 BEGIN TRANSACTION;

        UPDATE app.change_request
        SET request_status = N''CANCELLED'',
            updated_at_utc = SYSUTCDATETIME()
        WHERE request_id = @request_id AND request_status = @status AND row_version = @rowver;
        IF @@ROWCOUNT <> 1
            THROW 50149, N''Somebody else changed this request at the same moment: reload it and try again.'', 1;

        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, N''CANCELLED'', NULL, @actor, NULL, @cmt, @status, N''CANCELLED'', NULL);

        IF @own = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SET @o_new_status = N''CANCELLED'';
    IF @emit_result = 1
        SELECT @request_id AS request_id, @ref AS request_ref, @status AS previous_status, N''CANCELLED'' AS new_status;
END
');

PRINT N'=== end of app4_0_approval_rules ===';
